 ['title'=>'Bassengdrømmen','text'=>'Noen vil bade. Andre ønsker en rolig hage.','choices'=>[['id'=>'a','label'=>'Lag badeområde','effect'=>['joy'=>12,'cleanliness'=>-15,'coins'=>-15]],['id'=>'b','label'=>'Behold hageroen','effect'=>['energy'=>8,'joy'=>-3]]]],
