 ['title'=>'Frokostkø','text'=>'Alle kommer samtidig. Kjøkkenet trenger hjelp.','choices'=>[['id'=>'a','label'=>'Åpne ekstra buffet','effect'=>['joy'=>10,'coins'=>-12,'energy'=>-8]],['id'=>'b','label'=>'Server i to puljer','effect'=>['joy'=>-3,'energy'=>8]]]],
 ['title'=>'Regnværsdag','text'=>'Hagelekene regner bort. Gjester vil finne på noe inne.','choices'=>[['id'=>'a','label'=>'Lag inneverksted','effect'=>['joy'=>9,'cleanliness'=>-10]],['id'=>'b','label'=>'Lån ut bøker','effect'=>['joy'=>3,'energy'=>6]]]],
 ['title'=>'En sliten medarbeider','text'=>'Resepsjonen trenger pause midt i innsjekkingen.','choices'=>[['id'=>'a','label'=>'Gi en lang pause','effect'=>['energy'=>18,'joy'=>-5]],['id'=>'b','label'=>'Hent ekstra hjelp','effect'=>['energy'=>10,'coins'=>-15,'joy'=>4]]]],
