function effect(array &$s,array $e): void { foreach($e as $k=>$v)$s['metrics'][$k]=max(0,min($k==='coins'?999:100,$s['metrics'][$k]+$v)); foreach($s['guests'] as &$g){$g['mood']=max(0,min(100,($g['mood']??65)+($e['joy']??0)));$g['bubble']=$s['metrics']['cleanliness']<45?'Kan noen rydde litt?':($s['metrics']['joy']>=70?'Her vil jeg bo igjen!':'Hva skjer i hagen i dag?');} unset($g); }
function present(array $s,int $now): array {return array_values(array_column(array_filter($s['players'],fn($p)=>$p['seen']>=$now-45),'id'));}
function guestTradeoff(array &$s,string $kind): void {foreach($s['guests'] as &$g){$delta=0;$bubble='';if($kind==='party'){ $delta=$g['kind']==='rolig'?-20:10;$bubble=$g['kind']==='rolig'?'Jeg skulle ønske det var roligere.':'Kan vi danse litt til?';}if($kind==='pets'){$delta=$g['allergy']?-20:8;$bubble=$g['allergy']?'Jeg trenger et rom uten dyr.':'Så koselig med hund på besøk!';}if($kind==='pool'){$delta=$g['kind']==='aktiv'?15:3;$bubble='Jeg gleder meg til å bade!';$g['status']='pool';}if($delta){$g['mood']=max(0,min(100,$g['mood']+$delta));$g['bubble']=$bubble;}}unset($g);}
function startDay(array &$s,int $now): void { $s['day']++; $s['phase']='day';$s['dayEndsAt']=$now+$s['daySeconds'];$s['proposal']=null;foreach($s['players'] as &$p)$p['ready']=false;unset($p); $ev=events()[ (($s['season']-1)*5+$s['day']-1)%10]; $ev['id']='s'.$s['season'].'d'.$s['day'];$ev['resolved']=false;$s['event']=$ev; $s['guests']=[]; effect($s,match($s['profile']){'natur'=>['energy'=>5,'reputation'=>3],'luksus'=>['joy'=>6,'coins'=>-8],default=>['joy'=>3,'energy'=>3]}); effect($s,match($s['audience']){'venner'=>['joy'=>6,'energy'=>-5],'rolige'=>['energy'=>5,'joy'=>-1],default=>['joy'=>4,'cleanliness'=>-4]}); foreach(['Mia','Noah','Alma','Oliver','Ella','Leo'] as $i=>$name)$s['guests'][]=['id'=>$i+1,'name'=>$name,'room'=>$i+1,'kind'=>($i<3?match($s['audience']){'venner'=>'aktiv','rolige'=>'rolig',default=>'familie'}:['familie','rolig','aktiv'][$i%3]),'allergy'=>$i===1,'status'=>$i<2?'queue':'room','need'=>$i<2?'welcome':'serve','mood'=>$s['metrics']['joy'],'bubble'=>['Så fin hage!','Jeg er klar for frokost.','Hvor er resepsjonen?'][$i%3]]; effect($s,match($s['priority']){'mat'=>['joy'=>5,'coins'=>-4],'aktiviteter'=>['joy'=>6,'energy'=>-4],'personale'=>['energy'=>9,'coins'=>-4],default=>['cleanliness'=>8]}); }
function tick(array &$s,int $now): void { if($s['phase']==='day'&&$now>=$s['dayEndsAt']) {if(!$s['event']['resolved'])$s['history'][]='Dag '.$s['day'].': Dere lot gjestene finne egne løsninger.';effect($s,['cleanliness'=>in_array('pool',$s['upgrades'])?-14:-6,'energy'=>-7,'coins'=>12]);$s['phase']=$s['day']===5?'finished':'evening';$s['proposal']=null;$s['newspaper'][]=['day'=>$s['day'],'headline'=>$s['metrics']['joy']>=65?'Gjestene fant gode øyeblikk':'Gjestene ønsker noen endringer','text'=>'Trivsel '.$s['metrics']['joy'].' · Renhold '.$s['metrics']['cleanliness'].' · Overskudd '.$s['metrics']['energy'],'reactions'=>[$s['metrics']['cleanliness']>=60?'Rommet mitt var koselig og rent.':'Rommet trenger litt mer stell.',$s['metrics']['energy']>=50?'Vi fikk en varm velkomst.':'De ansatte hadde en travel dag.']];if($s['phase']==='finished'){ $prize=['shell','lantern','butterfly'][($s['season']-1)%3];if(!in_array($prize,$s['keepsakes']))$s['keepsakes'][]=$prize; }$s['rev']++; } resolveVote($s,$now); if(in_array($s['phase'],['planning','evening'])){$active=present($s,$now);$ready=array_column(array_filter($s['players'],fn($p)=>$p['ready']),'id');if($active&&!array_diff($active,$ready)){startDay($s,$now);$s['rev']++;}} }
function resolveVote(array &$s,int $now): void {if(!$s['proposal'])return;$active=present($s,$now);if(!$active)return;$need=count($active)===3?2:count($active);$counts=[];foreach($s['proposal']['votes'] as $id=>$choice)if(in_array($id,$active))$counts[$choice]=($counts[$choice]??0)+1;foreach($counts as $choice=>$count)if($count>=$need){$p=$s['proposal'];$s['proposal']=null;if($choice==='no'){$s['history'][]='Forslaget ble lagt bort.';$s['rev']++;return;}if($p['kind']==='event'){foreach($s['event']['choices'] as $c)if($c['id']===$choice){effect($s,$c['effect']);if($s['event']['title']==='Bassengdrømmen'&&$choice==='a'&&!in_array('pool',$s['upgrades']))$s['upgrades'][]='pool';if($choice==='a')guestTradeoff($s,match($s['event']['title']){'Bassengdrømmen'=>'pool','Fest i hagen'=>'party','En hund på døra'=>'pets',default=>''});$s['event']['resolved']=true;$s['event']['chosen']=$choice;$s['history'][]=$s['event']['title'].': '.$c['label'];}}else { $kind=$p['kind'];$effects=['pool'=>['joy'=>15,'coins'=>-30,'cleanliness'=>-10],'party'=>['joy'=>10,'energy'=>-15],'pets'=>['joy'=>8,'cleanliness'=>-10],'quiet'=>['energy'=>10,'joy'=>-3]];effect($s,$effects[$kind]);guestTradeoff($s,$kind);if($kind==='pool')$s['upgrades'][]='pool';$s['history'][]=['pool'=>'Dere bygget basseng.','party'=>'Dere arrangerte hagefest.','pets'=>'Dyregjester fikk komme.','quiet'=>'Dere valgte en rolig kveld.'][$kind];}$s['rev']++;return;}}
function publicState(array $s,int $now): array {$s['hotelName']=$s['hotelName']??'Hotellet vårt';unset($s['handled'],$s['qa']);foreach($s['players'] as &$p){$p['online']=$p['seen']>=$now-45;unset($p['lastSmall'],$p['seen']);}unset($p);return $s;}
function action(array &$s,string $who,array $in,int $now): void { $a=$in['action']??'';foreach($s['players'] as &$p)if($p['id']===$who){$player=&$p;break;}unset($p);
 if($a==='role'){if(!in_array($in['role']??'', ['fri','resepsjon','rom','hage','kjokken']))fail('Velg en rolle.');$player['role']=$in['role'];}
 elseif($a==='configure'){if($s['phase']!=='planning')fail('Neste sesong kan planlegges etter dag fem.'); if(array_key_exists('hotelName',$in)){$name=$in['hotelName'];if(!is_string($name)||strlen($name)>160||!preg_match('//u',$name)||preg_match('/[<>\p{C}]/u',$name))fail('Hotellnavnet må ha 2–40 tegn, uten spesialkoder.');$name=preg_replace('/^\s+|\s+$/u','',$name);if(!preg_match('/^.{2,40}$/uD',$name))fail('Hotellnavnet må ha 2–40 tegn.');$s['hotelName']=$name;} foreach(['profile'=>['koselig','luksus','natur'],'audience'=>['familier','venner','rolige'],'priority'=>['rom','mat','aktiviteter','personale']] as $k=>$allowed)if(isset($in[$k])){if(!in_array($in[$k],$allowed,true))fail('Ukjent valg.');$s[$k]=$in[$k];}foreach($s['players'] as &$p)$p['ready']=false;unset($p);}
 elseif($a==='decorate'){ $i=(int)($in['room']??0)-1;if($i<0||$i>5)fail('Ukjent rom.');if(isset($in['color'])){if(!in_array($in['color'],['peach','mint','lavender','sky','sunshine','rose']))fail('Ukjent farge.');$s['rooms'][$i]['color']=$in['color'];}if(isset($in['decor'])){if(!in_array($in['decor'],array_merge(['flowers','plant','stars','books'], $s['keepsakes'])))fail('Pynten er ikke tilgjengelig.');$s['rooms'][$i]['decor']=$in['decor'];}}
 elseif($a==='small'){if($s['phase']!=='day')fail('Åpne hotellet først.');$effects=['welcome'=>['joy'=>3,'reputation'=>1],'clean'=>['cleanliness'=>8,'energy'=>-2],'serve'=>['joy'=>5,'energy'=>-2],'garden'=>['joy'=>3,'energy'=>2]];$kind=$in['kind']??'';if(!isset($effects[$kind]))fail('Ukjent handling.');if($now-$player['lastSmall']<3)fail('Et lite øyeblikk – du hjelper allerede.',429);$player['lastSmall']=$now;effect($s,$effects[$kind]);foreach($s['guests'] as &$g){if($kind==='welcome'&&$g['status']==='queue'){$g['status']='room';$g['need']='serve';$g['bubble']='Takk for hjelpen! Nå finner jeg rommet.';break;}if($kind==='serve'&&$g['need']==='serve'){$g['status']='dining';$g['need']='relax';$g['bubble']='Frokosten smaker godt!';$g['mood']=min(100,$g['mood']+8);break;}if($kind==='clean'){$g['bubble']='Så fint det ble her!';$g['mood']=min(100,$g['mood']+3);}}unset($g);}
 elseif($a==='propose'){if($s['phase']!=='day')fail('Forslag gjøres i løpet av dagen.');if($s['proposal'])fail('Stem på forslaget som allerede ligger der.');$kind=$in['kind']??'';if(!in_array($kind,['pool','party','pets','quiet','event']))fail('Ukjent forslag.');if($kind==='pool'&&(in_array('pool',$s['upgrades'])||$s['metrics']['coins']<30))fail('Basseng er allerede bygget eller dere trenger flere hotellmynter.');if($kind==='event'&&$s['event']['resolved'])fail('Hendelsen er allerede løst.');$choice=$kind==='event'?($in['choice']??'a'):'yes';if($kind==='event'&&!in_array($choice,['a','b']))fail('Ukjent valg.');$s['proposal']=['kind'=>$kind,'by'=>$who,'votes'=>[$who=>$choice],'createdAt'=>$now];resolveVote($s,$now);}
 elseif($a==='vote'){if(!$s['proposal'])fail('Ingen forslag å stemme på.');$choice=$in['choice']??'';$allowed=$s['proposal']['kind']==='event'?['a','b']:['yes','no'];if(!in_array($choice,$allowed))fail('Ukjent stemme.');$s['proposal']['votes'][$who]=$choice;resolveVote($s,$now);}
 elseif($a==='ready'){if(!in_array($s['phase'],['planning','evening']))fail('Vent til dagen er ferdig.');$player['ready']=true;$active=present($s,$now);$ready=array_column(array_filter($s['players'],fn($p)=>$p['ready']),'id');if(!array_diff($active,$ready))startDay($s,$now);}
 elseif($a==='newSeason'){if($s['phase']!=='finished')fail('Fullfør sesongen først.');$s['season']++;$s['phase']='planning';$s['day']=0;$s['event']=null;$s['guests']=[];$s['newspaper']=[];$s['history']=[];$s['metrics']['energy']=85;$s['metrics']['cleanliness']=85;foreach($s['players'] as &$p)$p['ready']=false;unset($p);}
 else fail('Ukjent handling.');$s['rev']++;
}

function ownerCommand(string $cmd,string $hotel,array $argv): array {return transact(function(&$db)use($cmd,$hotel,$argv){if($cmd==='create'){if(isset($db['hotels'][$hotel]))fail('Hotel exists.');$db['hotels'][$hotel]=initial(($argv[3]??'')==='qa',(int)($argv[4]??300));return ['created'=>$hotel];}if(!isset($db['hotels'][$hotel]))fail('Unknown hotel.');if($cmd==='status')return ['hotel'=>$hotel,'qa'=>$db['hotels'][$hotel]['qa'],'phase'=>$db['hotels'][$hotel]['phase'],'day'=>$db['hotels'][$hotel]['day'],'bindings'=>count(array_filter($db['keys'],fn($k)=>$k['hotel']===$hotel)),'players'=>array_map(function($p)use($db,$hotel){$bound=false;foreach($db['keys'] as $k)if($k['hotel']===$hotel&&$k['player']===$p['id'])$bound=true;$expires=null;foreach($db['invites'] as $v)if($v['hotel']===$hotel&&$v['player']===$p['id']&&$v['expires']>=time())$expires=$v['expires'];return ['id'=>$p['id'],'name'=>$p['name'],'bound'=>$bound,'inviteExpiresAt'=>$expires];},$db['hotels'][$hotel]['players'])];if($cmd==='delete-qa'){if(!$db['hotels'][$hotel]['qa'])fail('Only QA hotels can be deleted.');unset($db['hotels'][$hotel]);foreach(['keys','invites'] as $table)foreach($db[$table] as $key=>$v)if($v['hotel']===$hotel)unset($db[$table][$key]);return ['deleted'=>$hotel];}if(!in_array($cmd,['invite','reset']))fail('Unknown command.');$player=$argv[3]??'';if(!in_array($player,['bianca','leandra','rebecca']))fail('Unknown player.');if($cmd==='invite')foreach($db['keys'] as $k)if($k['hotel']===$hotel&&$k['player']===$player)fail('Player already bound; use reset to replace device.');foreach(['keys','invites'] as $table)foreach($db[$table] as $key=>$v)if($v['hotel']===$hotel&&$v['player']===$player)unset($db[$table][$key]);$t=token();$db['invites'][hash('sha256',$t)]=['hotel'=>$hotel,'player'=>$player,'expires'=>time()+7*86400];return ['player'=>$player,'url'=>'https://biancanoor.no/hotell/#invite='.$t,'expiresInDays'=>7];});}
